  function build(group, kbId, baseDay, embeddedAll) {
    return group.map(function (row, i) {
      var embedded = embeddedAll == null ? true : (row.length > 2 ? row[2] : true);
      return {
        id: kbId + '-' + String(i + 1).padStart(2, '0'),
        title: row[0],
        content: row[1],
        embedded: embedded,
        createdAt: '2026-10-' + String(baseDay + (i % 5)).padStart(2, '0') + 'T0' + (8 + (i % 9)) + ':' + String(12 + i * 3).padStart(2, '0') + ':00'
      };
    });
  }

